            parent.right = left;
        }
    }

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // If node is null or has no left child, rotation is not possible
    if (node == null || node.left == null) {
        return node;
    }

    TreeNode<T> leftChild = node.left;
    TreeNode<T> rightOfLeft = leftChild.right;

    // Perform rotation
    leftChild.right = node;
    node.left = rightOfLeft;

    // Update parent references
    leftChild.parent = node.parent;
    node.parent = leftChild;
    if (rightOfLeft != null) {
        rightOfLeft.parent = node;
    }

    // If node had a parent, update its child reference to the new root of rotated subtree
    if (leftChild.parent != null) {
        if (leftChild.parent.left == node) {
            leftChild.parent.left = leftChild;
        } else if (leftChild.parent.right == node) {
            leftChild.parent.right = leftChild;
        }
    }

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        return node;
    }
    node.left = leftChild.right;
    leftChild.right = node;
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // Perform a right rotation on the given node.
    // Returns the new parent (the left child) after rotation.
    if (node == null) {
        return null;
    }

    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        // Nothing to rotate
        return node;
    }

    // Detach left child's right subtree and adopt it as node's left subtree.
    node.left = leftChild.right;
    if (leftChild.right != null) {
        // Update parent pointer if the tree keeps parents.
        leftChild.right.parent = node;
    }

    // Place node as the right child of its former left child.
    leftChild.right = node;

    // Update parent links
    TreeNode<T> parent = node.parent;
    leftChild.parent = parent;
    node.parent = leftChild;

    // Reconnect from the grandparent if it exists.
    if (parent != null) {
        if (parent.left == node) {
            parent.left = leftChild;
        } else if (parent.right == node) {
            parent.right = leftChild;
        }
    }

    return leftChild;
}

