public String format(LoggingEvent event){
    try {
        if (event == null) {
            return "";
        }
        StringBuilder sb = new StringBuilder();

        // Timestamp
        long ts = event.getTimeStamp();
        java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS");
        sdf.setTimeZone(java.util.TimeZone.getDefault());
        sb.append(sdf.format(new java.util.Date(ts)));

        // Thread name
        sb.append(" [");
        String thread = event.getThreadName();
        sb.append(thread != null ? thread : "unknown");
        sb.append("] ");

        // Log level
        Object level = event.getLevel();
        sb.append(level != null ? level.toString() : "UNKNOWN");

        // Logger name
        String logger = event.getLoggerName();
        sb.append(" ").append(logger != null ? logger : "unknown");

        // Message
        String message = event.getMessage();
        sb.append(" - ").append(message != null ? message : "");

        // New line at the end for typical log formats
        sb.append(System.lineSeparator());

        return sb.toString();
    } catch (Exception e) {
        // If anything goes wrong return an empty string
        return "";
    }
}

