                .getMethod("getFormattedMessage");
        if (getFormattedMessage != null) {
            Object result = getFormattedMessage.invoke(event);
            if (result instanceof String) {
                return (String) result;
            }
        }
    } catch (Exception ignored) {
        // If any reflection call fails, fall through to fallback
    }
    try {
        // Fallback to the event's toString() representation
        return event.toString();
    } catch (Exception ignored) {
        // If even toString() fails, return an empty string
        return "";
    }
