    if (event == null) {
        return "";
    }
    try {
        StringBuilder sb = new StringBuilder();

        // Append level
        if (event.getLevel() != null) {
            sb.append("[").append(event.getLevel().toString()).append("] ");
        } else {
            sb.append("[UNKNOWN] ");
        }

        // Append timestamp in human‑readable form
        long time = 0;
        try {
            time = event.getTimeStamp();
        } catch (Throwable t) {
            // some implementations use getTimeMillis()
            try {
                time = event.getTimeMillis();
            } catch (Throwable t2) {
                // ignore, leave 0
            }
        }
        if (time != 0) {
            sb.append(new java.util.Date(time).toString()).append(" - ");
        }

        // Append message
        String msg = event.getMessage();
        if (msg != null) {
            sb.append(msg);
        } else {
            sb.append("<no message>");
        }

        return sb.toString();
    } catch (Exception e) {
        // In case of any unexpected exception, return an empty string
        return "";
    }
}

