private int parseEndOfLine(String headerPart, int end) {
    // Validate input parameters
    if (headerPart == null || headerPart.isEmpty()) {
        return -1;
    }
    // Ensure 'end' is within the valid range for searching
    if (end < 0 || end >= headerPart.length()) {
        return -1;
    }

    // Search for the CRLF sequence starting from 'end'
    int lineEndIdx = headerPart.indexOf("\r\n", end);
    // If CRLF not found, indicate failure
    return lineEndIdx >= 0 ? lineEndIdx : -1;
}

private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null) {
        throw new IllegalArgumentException("headerPart must not be null");
    }
    int len = headerPart.length();
    if (end < 0 || end >= len) {
        throw new IllegalArgumentException("end index out of bounds: " + end);
    }

    // start scanning from the given index
    for (int i = end; i < len - 1; i++) {
        char current = headerPart.charAt(i);
        if (current == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;  // return the index of the '\r' part of the CRLF sequence
        }
    }

    // If we reach the last character without finding a complete CRLF,
    // check if the last character itself is a lone '\n' and treat it as end of line.
    if (len > 0 && headerPart.charAt(len - 1) == '\n') {
        return len - 1;
    }

    // No CRLF sequence found
    return -1;
}

