    try {
        if (graph == null) {
            throw new IllegalArgumentException("Input graph must not be null");
        }
        // Identity mapping: each vertex maps to itself, and each edge maps to itself
        return new IsomorphicGraphMapping<>(v -> v, e -> e);
    } catch (Exception e) {
        throw new IllegalArgumentException("Unable to construct identity automorphism", e);
    }
}

