}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null.");
    }
    // Identity mapping: each vertex and edge map to themselves.
    return new IsomorphicGraphMapping<V,E>() {
        @Override
        public boolean containsVertexMapping(V vertex) {
            return vertex != null && graph.vertexSet().contains(vertex);
        }

        @Override
        public V getVertexMapping(V vertex) {
            if (!containsVertexMapping(vertex)) {
                throw new IllegalArgumentException("Vertex not part of the graph: " + vertex);
            }
            return vertex;
        }

        @Override
        public boolean containsEdgeMapping(E edge) {
            return edge != null && graph.edgeSet().contains(edge);
        }

        @Override
        public E getEdgeMapping(E edge) {
            if (!containsEdgeMapping(edge)) {
                throw new IllegalArgumentException("Edge not part of the graph: " + edge);
            }
            return edge;
        }
    };
}

public static <V,E> IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    try {
        // Construct maps that map each vertex/edge to itself
        Map<V, V> vertexMap = new java.util.HashMap<>();
        for (V v : graph.vertexSet()) {
            vertexMap.put(v, v);
        }

        Map<E, E> edgeMap = new java.util.HashMap<>();
        for (E e : graph.edgeSet()) {
            edgeMap.put(e, e);
        }

        // Create and return the identity mapping
        return new IsomorphicGraphMapping<>(graph, graph, vertexMap, edgeMap);
    } catch (Exception ex) {
        throw new RuntimeException("Failed to create identity mapping for graph", ex);
    }
}

