        throw new IOException("Cannot schedule file for deletion: " + file.getAbsolutePath(), e);
    }
}

/** Helper that recursively schedules a file or directory for deletion. */
private static void scheduleDeleteOnExit(File f) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children == null) { // null indicates an I/O error or lack of permissions
            throw new IOException("Unable to access directory: " + f.getAbsolutePath());
        }
        for (File child : children) {
            scheduleDeleteOnExit(child);
        }
    }
    f.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    // Register a shutdown hook that will delete the file or directory recursively
    Runtime.getRuntime().addShutdownHook(new Thread(() -> {
        try {
            deleteRecursively(file);
        } catch (Exception e) {
            // Suppress exceptions during shutdown and optionally log them
            // to help debugging, but we cannot throw from this thread
            System.err.println("Failed to delete " + file + " on JVM exit: " + e.getMessage());
            e.printStackTrace();
        }
    }));
}

/**
* Recursively deletes a file or directory. If the file is a directory,
* all contained files and sub‐directories are deleted first.
*
* @param f the file or directory to delete
* @throws IOException if any deletion fails
*/
private static void deleteRecursively(File f) throws IOException {
    if (!f.exists()) {
        // Nothing to delete, treat as success
        return;
    }
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursively(child);
            }
        }
    }
    if (!f.delete()) {
        throw new IOException("Failed to delete file or directory: " + f);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (!file.exists()) {
        throw new FileNotFoundException("File does not exist: " + file);
    }
    try {
        // Register the file/directory for deletion first so that it is deleted after its contents.
        file.deleteOnExit();
        if (file.isDirectory()) {
            File[] children = file.listFiles();
            if (children == null) {
                throw new IOException("Failed to list contents of directory: " + file);
            }
            for (File child : children) {
                if (child != null) {
                    forceDeleteOnExit(child);
                }
            }
        }
    } catch (SecurityException se) {
        throw new IOException("Security violation while scheduling deletion for: " + file, se);
    }
}

