}

private static void scheduleDeletion(java.io.File f) throws java.io.IOException {
    if (f.isDirectory()) {
        java.io.File[] children = f.listFiles();
        if (children == null) {
            throw new java.io.IOException("Failed to list directory: " + f);
        }
        for (java.io.File child : children) {
            scheduleDeletion(child);
        }
    }
    try {
        f.deleteOnExit();
    } catch (SecurityException e) {
        throw new java.io.IOException("Cannot register deleteOnExit for: " + f, e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    // Register a shutdown hook that deletes the file/directory recursively
    String absPath = file.getAbsolutePath();
    synchronized (ForceDeleteOnExit.class) {
        // Prevent multiple hooks for the same absolute path
        if (!scheduledPaths.contains(absPath)) {
            scheduledPaths.add(absPath);
            Runtime.getRuntime().addShutdownHook(new Thread(() -> {
                try {
                    deleteRecursively(file);
                } catch (IOException e) {
                    // Deletion at exit can't throw checked exception, so log the failure
                    System.err.println("Failed to delete " + absPath + " on exit: " + e.getMessage());
                }
            }));
        }
        // If already scheduled, do nothing
    }
}

