        throw new IllegalArgumentException("Result map must not be null.");
    }

    // Define the sizes of the two partitions
    final int leftSize = 4;  // number of vertices in the first partition
    final int rightSize = 3; // number of vertices in the second partition

    try {
        // Create vertices for the left partition
        for (int i = 1; i <= leftSize; i++) {
            String id = "U" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) id;
            target.addVertex(vertex);
            resultMap.put(id, vertex);
        }

        // Create vertices for the right partition
        for (int j = 1; j <= rightSize; j++) {
            String id = "V" + j;
            @SuppressWarnings("unchecked")
            V vertex = (V) id;
            target.addVertex(vertex);
            resultMap.put(id, vertex);
        }

        // Add all edges between partitions (complete bipartite)
        for (int i = 1; i <= leftSize; i++) {
            String leftId = "U" + i;
            V u = resultMap.get(leftId);
            for (int j = 1; j <= rightSize; j++) {
                String rightId = "V" + j;
                V v = resultMap.get(rightId);
                target.addEdge(u, v);
            }
        }
    } catch (RuntimeException ex) {
        throw new IllegalArgumentException("Failed to generate bipartite graph: " + ex.getMessage(), ex);
    }
}

