@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Validate inputs
    if(target == null){
        throw new IllegalArgumentException("Target graph must not be null");
    }
    if(resultMap == null){
        throw new IllegalArgumentException("Result map must not be null");
    }

    // Ensure all vertices from resultMap are in the graph
    for(V vertex : resultMap.values()){
        if(vertex == null) continue;
        try{
            if(!target.containsVertex(vertex)){
                target.addVertex(vertex);
            }
        }catch(RuntimeException e){
            // If the graph implementation does not support containsVertex, simply add
            try{
                target.addVertex(vertex);
            }catch(RuntimeException ex){
                // ignore
            }
        }
    }

    // Partition vertices into left and right sets based on key prefixes
    java.util.Set<V> left = new java.util.HashSet<>();
    java.util.Set<V> right = new java.util.HashSet<>();
    for(java.util.Map.Entry<String,V> entry : resultMap.entrySet()){
        String key = entry.getKey();
        V value = entry.getValue();
        if(key == null || value == null) continue;
        String keyLower = key.toLowerCase();
        if(keyLower.startsWith("l") || keyLower.startsWith("left")){
            left.add(value);
        }else if(keyLower.startsWith("r") || keyLower.startsWith("right")){
            right.add(value);
        }
    }

    // If either partition is empty, nothing to connect
    if(left.isEmpty() || right.isEmpty()){
        return;
    }

    // Add edges between every pair of left and right vertices
    for(V lv : left){
        for(V rv : right){
            if(lv == null || rv == null || lv.equals(rv)) continue;
            try{
                target.addEdge(lv, rv);
            }catch(RuntimeException e){
                // Some graph implementations may not allow duplicate edges or may require an explicit edge object.
                // In such cases we simply ignore the failure for this particular pair.
                continue;
            }
        }
    }
}

protected int findByte(byte value, int pos) {
    // Ensure the buffer exists
    if (buffer == null) {
        // If buffer is not initialized, we cannot search; return -1 to indicate not found
        return -1;
    }
    int len = buffer.length;

    // Clamp the starting position to a valid range
    if (pos < 0) {
        pos = 0;
    }
    if (pos >= len) {
        return -1; // starting position beyond the buffer; nothing to find
    }

    // Search linearly from the starting position
    for (int i = pos; i < len; i++) {
        if (buffer[i] == value) {
            return i; // byte found at this index
        }
    }
    return -1; // value not found in the buffer
}

