public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream is null");
    }
    if (message == null) {
        throw new NullPointerException("Message is null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema is null");
    }
    if (buffer == null) {
        // We can still operate without the buffer by allocating a temporary one if needed
        buffer = LinkedBuffer.allocate(128);
    }

    int size;
    try {
        size = schema.getSerializedSize(message);
        if (size < 0) {
            throw new IllegalArgumentException("Size cannot be negative");
        }
    } catch (NoSuchMethodError | IllegalArgumentException e) {
        // Fallback: compute size using CodedOutputStream on a buffer
        CodedOutputStream temp = CodedOutputStream.newInstance(buffer.getSize());
        schema.write(message, temp);
        size = temp.getTotalBytesRead(); // may not be accurate but best effort
    }

    // Write the length prefix as a varint
    try {
        // Reserve n bytes for length marker (max 5 bytes for 32-bit int)
        CodedOutputStream cos = CodedOutputStream.newInstance(out, Math.max(5, size));
        cos.writeRawVarint32(size);
        schema.write(message, cos);
        cos.flush();
    } catch (IOException e) {
        throw new IOException("Failed to write delimited message", e);
    }
