protected void subAppend(LoggingEvent event){
    // Guard against null events
    if (event == null) {
        return;
    }
    try {
        // Retrieve the formatted message from the event.
        // Most logging frameworks provide getFormattedMessage() (Log4j 1.x/2.x) and getRenderedMessage() (Logback).
        // We use getFormattedMessage() here but fall back to getRenderedMessage() if necessary.
        String msg;
        try {
            msg = event.getFormattedMessage();
        } catch (NoSuchMethodError e) {
            // Fallback for frameworks that expose getRenderedMessage()
            msg = (String) event.getClass().getMethod("getRenderedMessage").invoke(event);
        }

        // Basic output: write the message to the console.
        // In a real appender, you would write to a stream, file, socket, etc.
        System.out.println(msg);
    } catch (Exception e) {
        // If any exception occurs during appending, log it to System.err to avoid silent failures.
        System.err.println("Error while appending log event: " + e.getMessage());
        e.printStackTrace(System.err);
