            // Attempt to detect the system drive from the WINDIR variable or default to C:
            String windir = System.getenv("WINDIR");
            String systemDrive = (windir != null && windir.length() >= 3) ? windir.substring(0, 3) : "C:\\";
            dirPath = systemDrive + "Documents and Settings" + java.io.File.separator + "lf5";
        } else {
