    // Ensure we do not read past the end of the provided array
    if (offset + len > data.length) {
        return false;
    }
    // Reference to the internal array (assumed field named 'data')
    byte[] internal = this.data;
    if (internal == null) {
        return false;
    }
    // Length must match exactly
    if (internal.length != len) {
        return false;
    }
    // Element‑wise comparison
    for (int i = 0; i < len; i++) {
        if (internal[i] != data[offset + i]) {
            return false;
        }
    }
    return true;
}

