public synchronized void send(final String message) {
    if (message == null) {
        return;
    }
    // Convert message to telnet-friendly format (CRLF line endings)
    String formatted = message.replace("\n", "\r\n");
    if (!formatted.endsWith("\r\n")) {
        formatted += "\r\n";
    }
    if (clients == null) {
        return;
    }
    for (Client client : clients) {
        if (client == null) {
            continue;
        }
        try {
            client.send(formatted);
        } catch (Exception ignored) {
            // Silently ignore failures for individual clients
        }
    }
}

public synchronized void send(final String message) {
    // Do nothing if the message is null
    if (message == null) {
        return;
    }

    // Telnet uses CRLF as the line separator
    final String telnetMessage = message + "\r\n";

    // Make a copy of the client writer list to avoid ConcurrentModificationException
    java.util.List<java.io.PrintWriter> writers;
    synchronized (clientWriters) {
        writers = new java.util.ArrayList<>(clientWriters);
    }

    for (java.io.PrintWriter writer : writers) {
        try {
            writer.print(telnetMessage);
            writer.flush();
        } catch (Exception e) {
            // If we cannot write to this writer, remove it from the main list
            synchronized (clientWriters) {
                clientWriters.remove(writer);
            }
            try {
                writer.close();
            } catch (Exception closeEx) {
                // ignore close exception
            }
        }
    }
}

public synchronized void send(final String message){
    if (message == null) {
        return;
    }
    String toSend = message + "\r\n";
    java.util.ArrayList<java.io.PrintWriter> toRemove = new java.util.ArrayList<>();
    for (java.io.PrintWriter out : clientWriters) {
        try {
            out.write(toSend);
            out.flush();
        } catch (java.io.IOException e) {
            toRemove.add(out);
        }
    }
    clientWriters.removeAll(toRemove);
}

