protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input
    if (start > end) {
        throw new IllegalArgumentException("start must be less than or equal to end");
    }
    // Ensure FETCH_DATA_DURATION is positive
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be a positive value");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long currentStart = start;
    while (currentStart < end) {
        long currentEnd = Math.min(currentStart + maxDuration, end);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Validate input
    if (start >= end) {
        // No data to fetch if start is not less than end
        return new ArrayList<>();
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }

    List<TimeRange> ranges = new ArrayList<>();
    long cur = start;
    while (cur < end) {
        long remaining = end - cur; // guaranteed non-negative
        long next;
        if (remaining <= FETCH_DATA_DURATION) {
            next = end;
        } else {
            // cur + FETCH_DATA_DURATION is safe because remaining > FETCH_DATA_DURATION
            next = cur + FETCH_DATA_DURATION;
        }
        // Safety check to avoid infinite loop on overflow edge case
        if (next <= cur) {
            break;
        }
        ranges.add(new TimeRange(cur, next));
        cur = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges;
    }
    if (start < 0 || end < 0) {
        throw new IllegalArgumentException("Start and end times must be non-negative");
    }
    try {
        for (long s = start; s < end; s += FETCH_DATA_DURATION) {
            long e = Math.min(s + FETCH_DATA_DURATION, end);
            ranges.add(new TimeRange(s, e));
        }
    } catch (ArithmeticException ex) {
        throw new RuntimeException("Overflow while splitting time ranges", ex);
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Return an empty list if the range is invalid
    if (start >= end) {
        return new ArrayList<>();
    }

    List<TimeRange> ranges = new ArrayList<>();

    // Ensure no overflow by using a while loop with precise calculations
    long currentStart = start;
    while (currentStart < end) {
        long maxPossibleEnd = currentStart + FETCH_DATA_DURATION;
        // Avoid overflow: if addition wraps around, treat maxPossibleEnd as Long.MAX_VALUE
        if (maxPossibleEnd < currentStart) {
            maxPossibleEnd = Long.MAX_VALUE;
        }
        long currentEnd = Math.min(end, maxPossibleEnd);
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
        // Break if currentStart does not progress to avoid infinite loop (safety)
        if (currentStart == end) {
            break;
        }
        if (currentStart < start) { // In case of underflow
            break;
        }
    }

    return ranges;
}

protected java.util.List<TimeRange> buildTimeRanges(long start, long end) {
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    try {
        // Normalize input: if start is negative set to 0, same for end
        long s = Math.max(0L, start);
        long e = Math.max(0L, end);
        if (s >= e) {
            // Empty range, nothing to split
            return ranges;
        }

        // Ensure FETCH_DATA_DURATION is a positive value
        if (java.lang.Math.abs(FETCH_DATA_DURATION) <= 0L) {
            throw new java.lang.IllegalStateException("FETCH_DATA_DURATION must be positive");
        }

        long interval = java.lang.Math.abs(FETCH_DATA_DURATION);

        long current = s;
        while (current < e) {
            long next = current + interval;
            if (next > e) {
                next = e;
            }
            ranges.add(new TimeRange(current, next));
            current = next;
        }
    } catch (Exception ex) {
        // In case of unexpected errors, return what has been built so far or an empty list
        return new java.util.ArrayList<>();
    }
    return ranges;
}

