        case 9:  daysInMonth = 30; break;
        case 10: daysInMonth = 31; break;
        case 11: daysInMonth = 30; break;
        case 12: daysInMonth = 31; break;
        default: throw new IllegalArgumentException("Invalid month value");
    }

    if (day < 1 || day > daysInMonth) {
        throw new IllegalArgumentException("Invalid day in timeBucket");
    }

    long bucketDay = ((day - 1) / dayStep) * dayStep + 1;
    if (bucketDay > daysInMonth) {
