        } else {
            // Possible surrogate pair?
            if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
                // Valid surrogate pair -> 4 bytes
                size += 4;
                i++; // skip low surrogate
            } else {
                // Invalid surrogate or lone surrogate -> 3 bytes
                size += 3;
            }
        }
    }
