    int end = index + len;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else {
            // Check for surrogate pair
            if (ch >= 0xD800 && ch <= 0xDBFF) { // high surrogate
                if (i + 1 < end) {
                    char next = str.charAt(i + 1);
                    if (next >= 0xDC00 && next <= 0xDFFF) { // low surrogate
                        size += 4;
                        i += 2;
                        continue;
                    }
                }
                // Unpaired high surrogate: encode as 3 bytes
                size += 3;
            } else if (ch >= 0xDC00 && ch <= 0xDFFF) { // unpaired low surrogate
                size += 3;
            } else { // U+0800 to U+FFFF
                size += 3;
            }
        }
        i++;
    }
    return size;
}

