    }
    if (index < 0 || len < 0 || index > str.length() || len > str.length() - index) {
        throw new IndexOutOfBoundsException("index or length out of range");
    }
    int bytes = 0;
    int end = index + len;
    for (int i = index; i < end; ) {
        char c = str.charAt(i);
        if (c < 0x80) {
            bytes += 1;
        } else if (c < 0x800) {
            bytes += 2;
        } else if (Character.isHighSurrogate(c) && i + 1 < end
                && Character.isLowSurrogate(str.charAt(i + 1))) {
            // Surrogate pair -> 4 bytes
            bytes += 4;
            i++; // skip low surrogate
        } else {
            // BMP character (including unpaired surrogates) -> 3 bytes
            bytes += 3;
        }
        i++;
    }
    return bytes;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("str");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException("index=" + index + ", len=" + len + ", length=" + str.length());
    }
    int end = index + len;
    int bytes = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end && Character.isLowSurrogate(str.charAt(i + 1))) {
            codePoint = Character.toCodePoint(ch, str.charAt(i + 1));
            i++; // Skip the low surrogate
        } else if (Character.isSurrogate(ch)) {
            // Unpaired surrogate, treat as replacement character U+FFFD
            codePoint = 0xFFFD;
        } else {
            codePoint = ch;
        }

        // Determine UTF‑8 byte length for codePoint
        if (codePoint <= 0x7F) {
            bytes += 1;
        } else if (codePoint <= 0x7FF) {
            bytes += 2;
        } else if (codePoint <= 0xFFFF) {
            bytes += 3;
        } else {
            bytes += 4;
        }

        i++;
    }
    return bytes;
}

