    int len = str.length();

    // Clamp start and end to the valid range [0, len]
    start = Math.max(0, Math.min(start, len));
    end   = Math.max(0, Math.min(end,   len));

    // If the resulting indices are not in order, return empty string
    if (start >= end) {
        return "";
    }

    // Return the safe substring
    return str.substring(start, end);
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength){
    // Validate length
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // Validate source array bounds
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength) {
            throw new ArrayIndexOutOfBoundsException("byteOffset and byteLength out of bounds for source array");
        }
    }
    // Calculate required capacity
    int required = this.size + byteLength;
    // Resize buffer if necessary
    if (required > (buffer == null ? 0 : buffer.length)) {
        int newCapacity = buffer == null ? required : Math.max(buffer.length * 2, required);
        // Prevent overflow
        if (newCapacity < 0) {
            newCapacity = Integer.MAX_VALUE;
        }
        byte[] newBuffer = new byte[newCapacity];
        if (buffer != null && this.size > 0) {
            System.arraycopy(buffer, 0, newBuffer, 0, this.size);
        }
        buffer = newBuffer;
    }
    // Copy or fill
    if (byteArrayValue == null) {
        // Fill with zeros
        for (int i = 0; i < byteLength; i++) {
            buffer[this.size + i] = 0;
        }
    } else if (byteLength > 0) {
        System.arraycopy(byteArrayValue, byteOffset, buffer, this.size, byteLength);
    }
    // Update size
    this.size += byteLength;
    return this;
}

