    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non‑negative");
    }
    if (byteOffset < 0) {
        throw new IllegalArgumentException("byteOffset must be non‑negative");
    }

    // Special case: null source array means insert byteLength zero‑bytes
    if (byteArrayValue == null) {
        if (byteLength == 0) {
            return this;
        }
        int newSize = length + byteLength;
        if (newSize < 0) { // overflow guard
            throw new IllegalStateException("ByteVector too large");
        }
        if (newSize > buffer.length) {
            int newCap = Math.max(newSize, buffer.length * 2 + 1);
            byte[] newBuf = new byte[newCap];
            System.arraycopy(buffer, 0, newBuf, 0, length);
            buffer = newBuf;
        }
        java.util.Arrays.fill(buffer, length, newSize, (byte)0);
        length = newSize;
        return this;
    }

    // Validate offset and length relative to source array
    if (byteOffset > byteArrayValue.length - byteLength) {
        throw new IndexOutOfBoundsException("byteOffset + byteLength exceed source array length");
    }

    int newSize = length + byteLength;
    if (newSize < 0) {
