        double halfWidth = fullWidth / 2.0;
        double centerX = box.getCenterX();
        double centerY = box.getCenterY();
        double height = box.getHeight();

        Box2D leftBox  = new Box2D(centerX - halfWidth / 2.0, centerY, halfWidth, height);
        Box2D rightBox = new Box2D(centerX + halfWidth / 2.0, centerY, halfWidth, height);

        return new Pair<>(leftBox, rightBox);
    } catch (Exception e) {
