        double maxX = box.getMaxX();
        double minY = box.getMinY();
        double maxY = box.getMaxY();

        // Ensure minX <= maxX for consistency
        if (minX > maxX) {
            double tmp = minX;
            minX = maxX;
            maxX = tmp;
