private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        throw new IllegalArgumentException("Input sets cannot be null");
    }

    // Choose the smaller set for iteration to reduce checks
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger = set1.size() <= set2.size() ? set2 : set1;

    Set<V> result = new HashSet<>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    Set<V> result = new HashSet<>();
    if (set1 == null || set2 == null) {
        return result; // Treat null as empty set
    }
    if (set1.isEmpty() || set2.isEmpty()) {
        return result; // No intersection possible
    }
    // Iterate over the smaller set for efficiency
    if (set1.size() > set2.size()) {
        for (V elem : set2) {
            if (set1.contains(elem)) {
                result.add(elem);
            }
        }
    } else {
        for (V elem : set1) {
            if (set2.contains(elem)) {
                result.add(elem);
            }
        }
    }
    return result;
}

