private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start and stop nodes must not be null.");
    }
    // If the start node already satisfies the predicate, return a circulator pointing to it.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start, dir);
    }
    // Otherwise, return a circulator pointing to the stop node.
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }
    if (dir != 1 && dir != -1) {
        throw new IllegalArgumentException("dir must be 1 (forward) or -1 (backward)");
    }

    try {
        // Construct a circulator that points to the start node and is configured with the given direction.
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

        // If the starting node already satisfies the predicate, return it immediately.
        if (predicate.test(circ.node())) {
            return circ;
        }

        // Walk around the outer face until we either hit the stop node or find a node satisfying the predicate.
        while (!circ.node().equals(stop)) {
            circ.next(); // advance according to the direction set in the circulator
            if (predicate.test(circ.node())) {
                return circ;
            }
        }

        // If we exit the loop, we are at the stop node, so return that circulator.
        return circ;
    } catch (Exception e) {
        // Any unforeseen runtime exception is wrapped to provide contextual information.
        throw new RuntimeException("Failed to select a circulator on the outer face", e);
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Validate inputs
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }

    // If start is the same as stop, simply test the node once
    if (start.equals(stop)) {
        return predicate.test(start) ? new OuterFaceCirculator(start) : new OuterFaceCirculator(stop);
    }

    Node current = start;

    // Traverse until we reach the stop node
    while (!current.equals(stop)) {
        try {
            if (predicate.test(current)) {
                return new OuterFaceCirculator(current);
            }
        } catch (RuntimeException e) {
            // If predicate evaluation fails, wrap and rethrow
            throw new RuntimeException("Predicate evaluation failed for node: " + current, e);
        }

        // Move to the next node in the specified direction
        Node next = current.next(dir); // Assuming Node has a next(int dir) method
        if (next == null) {
            // If we cannot find a next node, break to avoid infinite loop
            break;
        }
        current = next;
    }

    // If no node satisfied the predicate, return a circulator to the stop node
    return new OuterFaceCirculator(stop);
}

