        throw new IllegalArgumentException("Edge source cannot be null");
    }
    orderedVertices.add(startVertex);
    orderedEdges.add(first);
    V currentVertex = graph.getEdgeTarget(first);
    if (currentVertex == null) {
        throw new IllegalArgumentException("Edge target cannot be null");
    }

    // If the graph is directed we just follow source->target.
    // If it is undirected or the edge is reversed we try to flip.
    boolean directed = graph.getType().isDirected();

    while (!remaining.isEmpty()) {
        E next = null;
        for (E e : remaining) {
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            boolean match;
            if (directed) {
                match = src.equals(currentVertex);
            } else {
                match = src.equals(currentVertex) || tgt.equals(currentVertex);
            }
            if (match) {
                next = e;
                break;
            }
        }

        if (next == null) {
            // No connecting edge found – terminate the path
            break;
        }

        orderedEdges.add(next);
        V src = graph.getEdgeSource(next);
        V tgt = graph.getEdgeTarget(next);
        V nextVertex = src.equals(currentVertex) ? tgt : src;
        orderedVertices.add(nextVertex);
        currentVertex = nextVertex;
        remaining.remove(next);
    }

    return new DefaultGraphPath<>(graph, orderedVertices, orderedEdges);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null){
        throw new NullPointerException("Tour and graph must not be null");
    }
    // Build adjacency map: vertex -> set of incident edges
    Map<V, Set<E>> adjacency = new HashMap<>();
    for (E e : tour){
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(src, k -> new HashSet<>()).add(e);
        if (!graph.isDirected()){
            adjacency.computeIfAbsent(tgt, k -> new HashSet<>()).add(e);
        }
    }
    // Choose a start vertex: prefer one with degree 1 (path start/end), otherwise any
    V start = null;
    for (Map.Entry<V, Set<E>> entry : adjacency.entrySet()){
        if (adjacency.get(entry.getKey()).size() == 1){
            start = entry.getKey();
            break;
        }
    }
    if (start == null){
        start = adjacency.keySet().iterator().next(); // arbitrary
    }
    List<E> orderedEdges = new ArrayList<>();
    Set<E> visited = new HashSet<>();
    V current = start;
    // Traverse edges
    for (int i = 0; i < tour.size(); i++){
        Set<E> incident = adjacency.get(current);
        if (incident == null){
            throw new IllegalArgumentException("Current vertex has no incident edges but tour continues");
        }
        E nextEdge = null;
        for (E e : incident){
            if (visited.contains(e)){
                continue;
            }
            if (graph.isDirected()){
                // Edge must go out from current
                if (!graph.getEdgeSource(e).equals(current)){
                    continue;
                }
            } else {
                // For undirected, any edge works
            }
            nextEdge = e;
            break;
        }
        if (nextEdge == null){
            // For undirected case, might need to consider reversed orientation
            for (E e : incident){
                if (visited.contains(e)){
                    continue;
                }
                nextEdge = e;
                break;
            }
        }
        if (nextEdge == null){
            throw new IllegalArgumentException("Unable to find next edge to extend path. Tour may be disconnected or invalid");
        }
        visited.add(nextEdge);
        orderedEdges.add(nextEdge);
        // Move to next vertex
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        current = graph.isDirected() ? tgt : (src.equals(current) ? tgt : src);
    }
    V end = current;
    double weight = 0.0;
    for (E e : orderedEdges){
        weight += graph.getEdgeWeight(e);
    }
    return new GraphWalk<>(graph, start, end, orderedEdges, weight);
}

