private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    // If the identifier is not quoted, return it unchanged
    if (!input.startsWith("\"") || !input.endsWith("\"") || input.length() < 2) {
        return input;
    }

    // Remove the surrounding quotes
    String inner = input.substring(1, input.length() - 1);
    StringBuilder sb = new StringBuilder(inner.length());

    for (int i = 0; i < inner.length(); i++) {
        char c = inner.charAt(i);
        if (c == '\\' && i + 1 < inner.length()) {
            char next = inner.charAt(++i);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                default:
                    // If the escape sequence is not recognized, keep the next character literally
                    sb.append(next);
                    break;
            }
        } else {
            sb.append(c);
        }
    }

    return sb.toString();
}

