private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate input ranges
    if (bucketsByLabel == null || labels == null || bucketsByLabel.isEmpty()) {
        return;
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        return;
    }

    Set<Integer> minBucket = bucketsByLabel.get(minLabel);
    if (minBucket == null || minBucket.isEmpty()) {
        return;
    }

    // Ensure bucket 0 exists
    Set<Integer> zeroBucket = bucketsByLabel.get(0);
    if (zeroBucket == null) {
        zeroBucket = new java.util.HashSet<>();
        // Expand the list if necessary
        while (bucketsByLabel.size() <= 0) {
            bucketsByLabel.add(null);
        }
        bucketsByLabel.set(0, zeroBucket);
    }

    for (Integer vertex : minBucket) {
        if (vertex == null) continue;
        // Update label if within bounds
        if (vertex >= 0 && vertex < labels.size()) {
            labels.set(vertex, 0);
        }
        zeroBucket.add(vertex);
    }

    // Clear the original bucket
    minBucket.clear();
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Validate input
    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds: " + minLabel);
    }

    // Grab the bucket that contains the vertices to move
    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    if (sourceBucket == null || sourceBucket.isEmpty()) {
        // Nothing to do: ensure the bucket is present (empty) if needed
        bucketsByLabel.set(minLabel, new HashSet<>());
        return;
    }

    // Ensure bucket 0 exists
    Set<Integer> targetBucket = bucketsByLabel.get(0);
    if (targetBucket == null) {
        targetBucket = new HashSet<>();
        bucketsByLabel.set(0, targetBucket);
    }

    // Move vertices from source to target bucket, updating labels
    for (Integer vertex : sourceBucket) {
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("Vertex index out of bounds: " + vertex);
        }
        labels.set(vertex, 0);
        targetBucket.add(vertex);
    }

    // Clear the source bucket
    sourceBucket.clear();
    // Optionally replace with a fresh empty set to avoid mutation by other references
    bucketsByLabel.set(minLabel, new HashSet<>());
