/** 
 * Moves all vertices from the bucket with label {@code minLabel} to the bucket with label 0.
 * Clears the bucket with label {@code minLabel}. Updates the labeling accordingly.
 * @param bucketsByLabel the buckets vertices are stored in, indexed by label
 * @param labels the labels of the vertices
 * @param minLabel the minimum value of the non-empty bucket
 */
private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null) {
        throw new IllegalArgumentException("bucketsByLabel cannot be null");
    }
    if (labels == null) {
        throw new IllegalArgumentException("labels cannot be null");
    }
    if (minLabel < 0) {
        throw new IllegalArgumentException("minLabel cannot be negative: " + minLabel);
    }
    if (minLabel >= bucketsByLabel.size()) {
        // Nothing to move if the bucket does not exist
        return;
    }

    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    if (sourceBucket == null || sourceBucket.isEmpty()) {
        // Nothing to move
        return;
    }

    // Ensure destination bucket exists
    Set<Integer> destBucket = bucketsByLabel.get(0);
    if (destBucket == null) {
        destBucket = new java.util.HashSet<>();
        bucketsByLabel.set(0, destBucket);
    }

    for (Integer vertex : sourceBucket) {
        // Update label
        try {
            labels.set(vertex, 0);
        } catch (IndexOutOfBoundsException e) {
            throw new IllegalArgumentException("Vertex index out of bounds in labels list: " + vertex, e);
        }
        // Move vertex
        destBucket.add(vertex);
    }

    // Clear the source bucket
    sourceBucket.clear();
}

