    } else {
        // Node was the last element
        this.last = node.prev;
    }

    // Clean up the removed node’s references to help GC
    node.prev = null;
    node.next = null;

    // Adjust the size counter if it is still valid
    if (this.size > 0) {
        this.size--;
    }

    return true;
}

