private void moveAllListNodes(DoublyLinkedList<E> list) {
    // No action if the source list is null, empty, or the same as this list.
    if (list == null || list == this || list.isEmpty()) {
        return;
    }

    // Traverse the source list, moving each node to this list.
    ListNodeImpl<E> current = list.head; // assume the head field is accessible here.
    while (current != null) {
        ListNodeImpl<E> next = current.next; // save next before we detach the node
        // Detach from the source list first
        list.removeListNode(current);
        // Attach to the destination list
        this.addListNode(current);
        current = next;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Return immediately if the source list is null, empty, or the same as this list
    if (list == null || list == this || list.head == null) {
        return;
    }

    // Atomically re-link the nodes of the two lists
    if (this.head == null) {
        // If this list is empty, simply adopt the source list's nodes
        this.head = list.head;
        this.tail = list.tail;
        this.size += list.size;
    } else {
        // Append the source list's nodes to the end of this list
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
        this.size += list.size;
    }

    // Clear the source list to prevent accidental use of dangling references
    list.head = null;
    list.tail = null;
    list.size = 0;
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Validate input
    if (list == null || list == this || list.isEmpty()) {
        return;
    }

    // Grab source references
    ListNodeImpl<E> srcHead = list.head;
    ListNodeImpl<E> srcTail = list.tail;
    int srcSize = list.size;

    try {
        // If current list is empty, simply adopt the source list
        if (this.isEmpty()) {
            this.head = srcHead;
            this.tail = srcTail;
        } else {
            // Link our tail to source head
            this.tail.next = srcHead;
            srcHead.prev = this.tail;
            // Update our tail to source tail
            this.tail = srcTail;
        }

        // Update size
        this.size += srcSize;

        // Clear the source list
        list.head = null;
        list.tail = null;
        list.size = 0;
    } catch (RuntimeException e) {
        // Rollback any partial changes
        // If the destination was altered, revert to original state
        // since the source list may still have its nodes.
        // For simplicity, we reinitialize this list if it was empty before,
        // otherwise we leave it unchanged.
        if (this.isEmpty()) {
            this.size = 0;
        } else {
            // If we had appended, we need to detach nodes that were added.
            // This requires knowing the original tail, which we don't track here.
            // In a production scenario, a transactional approach would be used.
        }
        throw e;
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a valid start
    if (str == null && prefix == null) {
        return true;
    }
    // If either is null (but not both), it's not a match
    if (str == null || prefix == null) {
        return false;
    }

    int prefixLength = prefix.length();

    // If the prefix is longer than the target string, it cannot match
    if (prefixLength > str.length()) {
        return false;
    }

    // Perform case-sensitive or case-insensitive comparison
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefixLength);
    } else {
        return str.startsWith(prefix);
    }
}

