public static void selectRow(int row, javax.swing.JTable table, javax.swing.JScrollPane pane) {
    try {
        if (table == null || pane == null) {
            return;
        }
        int rowCount = table.getRowCount();
        if (row < 0 || row >= rowCount) {
            return;
        }
        // Select the specified row (and keep other selections cleared)
        table.clearSelection();
        table.setRowSelectionInterval(row, row);
        // Ensure the first column is visible so the rowRect can be computed
        table.setColumnSelectionInterval(0, 0);

        // Scroll the row into view
        java.awt.Rectangle cellRect = table.getCellRect(row, 0, true);
        if (cellRect != null) {
            table.scrollRectToVisible(cellRect);
        }

        // Delay repaint to allow the table to paint the newly selected row
        javax.swing.Timer repaintTimer = new javax.swing.Timer(50, e -> {
            table.repaint();
            pane.repaint();
            ((javax.swing.Timer) e.getSource()).stop();
        });
        repaintTimer.setRepeats(false);
        repaintTimer.start();
    } catch (Exception e) {
        // Fail silently – nothing can be done if UI components are not ready
    }
}

/**
 * Selects the specified row in the specified {@link JTable} and scrolls the specified {@link JScrollPane}
 * to make the newly selected row visible. The repaint is delayed to allow the table to fully paint the
 * selection, which is important if the row was initially off‑screen.
 *
 * @param row   the index of the row to select (0‑based)
 * @param table the {@link JTable} that should belong to the provided {@link JScrollPane}
 * @param pane  the {@link JScrollPane} containing the table
 */
public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Basic validation
    if (table == null || pane == null) {
        return; // Nothing to do
    }
    final int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount || rowCount == 0) {
        return; // Invalid row index
    }

    Runnable action = () -> {
        try {
            // Clear any existing column selection to avoid confusing visuals
            int columnCount = table.getColumnCount();
            if (columnCount > 0) {
                table.setColumnSelectionInterval(0, 0);
            }

            // Select the row
            table.setRowSelectionInterval(row, row);

            // Make sure the row is visible
            Rectangle rect = table.getCellRect(row, 0, true);
            if (rect != null) {
                table.scrollRectToVisible(rect);
            }

            // Delay repaint so that the table has time to process selection changes
            SwingUtilities.invokeLater(() -> table.repaint());
        } catch (Exception ex) {
            // Silently ignore any runtime issues; the method is defensive
        }
    };

    // Run the action on the EDT if we're already on it, otherwise post it
    if (SwingUtilities.isEventDispatchThread()) {
        action.run();
    } else {
        SwingUtilities.invokeLater(action);
    }
}

