    // Ensure there is a buffer to write into
    if (buffer == null) {
        buffer = new byte[4];
        count = 0;
    }

    // Ensure capacity for 4 more bytes
    int remaining = buffer.length - count;
    if (remaining < 4) {
        int newSize = Math.max(buffer.length * 2, count + 4);
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(buffer, 0, newBuffer, 0, count);
        buffer = newBuffer;
    }

    // Write the int in big‑endian order
    buffer[count++] = (byte) (intValue >>> 24);
    buffer[count++] = (byte) (intValue >>> 16);
    buffer[count++] = (byte) (intValue >>> 8);
    buffer[count++] = (byte) intValue;

    return this;
}

