            result.add(0);
            continue;
        }
        int idx = upperBoundIndex(sorted, key);
        result.add(idx);
    }
    return result;
}

private int upperBoundIndex(List<K> sorted, K key){
    int left = 0;
    int right = sorted.size();
    while (left < right) {
        int mid = (left + right) >>> 1;
        K midVal = sorted.get(mid);
        @SuppressWarnings("unchecked")
        Comparable<? super K> cmp = (Comparable<? super K>) midVal;
        if (cmp.compareTo(key) <= 0) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

