            return false;
        }
        long now = System.currentTimeMillis();
        if(timestamp > now){
            return false;
        }
        return now - timestamp > expiredThreshold;
    }catch(Exception e){
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // If the threshold is non‑positive, consider it already expired.
    if (expiredThreshold <= 0) {
        return true;
    }

    long currentTime = System.currentTimeMillis();
    try {
        // Compute the expiry moment and prevent overflow.
        long expiryTime = Math.addExact(timestamp, expiredThreshold);
        return currentTime >= expiryTime;
    } catch (ArithmeticException ex) {
        // Overflowed in addition – treat as expired to be safe.
        return true;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate input parameters
    if (expiredThreshold < 0) {
        throw new IllegalArgumentException("expiredThreshold must be non‑negative");
    }
    if (timestamp < 0) {
        throw new IllegalArgumentException("timestamp must be non‑negative");
    }

    long currentTimeMillis = System.currentTimeMillis();

    // If the timestamp is in the future, it cannot be expired yet
    if (timestamp > currentTimeMillis) {
        return false;
    }

    // Compute elapsed time safely
    long elapsed = currentTimeMillis - timestamp;
    return elapsed > expiredThreshold;
}

