    Object msgObj = event.getMessage();
    String message = (msgObj == null) ? "" : msgObj.toString();

    // Assume there is a field named 'clients' that holds all connected sockets
    if (clients == null) {
        return;
    }

    synchronized (clients) {
        Iterator<?> it = clients.iterator();
        while (it.hasNext()) {
            Object obj = it.next();
            if (!(obj instanceof Socket)) {
                // Skip non-socket objects
                continue;
            }
            Socket socket = (Socket) obj;
            try {
                if (socket != null && socket.isConnected() && !socket.isClosed()) {
                    PrintWriter pw = new PrintWriter(socket.getOutputStream(), true);
                    pw.println(message);
                } else {
                    // Remove stale or closed sockets
                    it.remove();
                }
            } catch (IOException io) {
                // On any I/O error, close the socket and remove it from the list
                try {
                    socket.close();
                } catch (IOException ignored) {
                }
                it.remove();
            } catch (RuntimeException re) {
                // Log or ignore unexpected runtime problems
                // The socket remains; skip sending this message
            }
        }
    }
}

protected void append(LoggingEvent event) {
    // Guard against null event
    if (event == null) {
        return;
    }

    // Prepare the message string safely
    String message;
    try {
        Object obj = event.getMessage();
        message = (obj == null) ? "" : obj.toString();
    } catch (Exception ex) {
        // If rendering the message fails, do not send anything
        return;
    }

    // Make a snapshot of connected clients to avoid concurrent modification
    Set<Object> snapshot;
    synchronized (this) {
        // Assume a field 'connectedClients' holds all client output streams;
        // if the field is missing or null, nothing can be sent.
        // Convert to Set<Object> to allow different client types.
        snapshot = (connectedClients != null) ? new HashSet<>(connectedClients) : null;
    }

    if (snapshot == null || snapshot.isEmpty()) {
        return; // No clients to notify
    }

    // Iterate over each client and attempt to write the message
    for (Object client : snapshot) {
        try {
            if (client instanceof PrintWriter) {
                PrintWriter pw = (PrintWriter) client;
                pw.println(message);
                pw.flush();
            } else if (client instanceof BufferedWriter) {
                BufferedWriter bw = (BufferedWriter) client;
                bw.write(message);
                bw.newLine();
                bw.flush();
            } else if (client instanceof Writer) {
                Writer w = (Writer) client;
                w.write(message + System.lineSeparator());
                w.flush();
            } else if (client instanceof OutputStream) {
                OutputStream os = (OutputStream) client;
                os.write((message + System.lineSeparator()).getBytes());
                os.flush();
            } else {
                // Unknown client type, attempt to stringify
                client.toString(); // Force potential exception to be caught
            }
        } catch (Exception ex) {
            // On any exception we remove the problematic client from the roster
            try {
                synchronized (this) {
                    if (connectedClients != null) {
                        connectedClients.remove(client);
                    }
                }
            } catch (Exception ignore) {
                // ignore removal failures
            }
        }
    }
}

