    if (message == null) {
        return;
    }

    // Take a snapshot to avoid concurrent modification issues
    Collection<Socket> clientSnapshot;
    synchronized (connections) {
        clientSnapshot = new ArrayList<>(connections);
    }

    for (Socket socket : clientSnapshot) {
        if (socket == null) {
