            writer.write(message);
            writer.newLine();
            writer.flush();
        } catch (IOException e) {
            // Client likely disconnected, remove it
            synchronized (connections) {
                connections.remove(socket);
            }
            try {
                socket.close();
            } catch (IOException ignore) {
            }
        } catch (Exception e) {
            // Handle any other unexpected exceptions gracefully
        }
    }
}

