public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File does not exist or is not a regular file: " + file);
    }

    List<ThreadSnapshot> result = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            // Expected line format: <timestamp>,<data>
            int commaIdx = line.indexOf(',');
            if (commaIdx < 0) {
                continue; // skip malformed line
            }

            long timestamp;
            try {
                timestamp = Long.parseLong(line.substring(0, commaIdx).trim());
            } catch (NumberFormatException e) {
                continue; // skip if timestamp cannot be parsed
            }

            String data = line.substring(commaIdx + 1).trim();

            // If timeRanges are null or empty, accept all snapshots
            boolean withinRange = true;
            if (timeRanges != null && !timeRanges.isEmpty()) {
                withinRange = false;
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    try {
                        long start = range.getStart();
                        long end = range.getEnd();
                        if (timestamp >= start && timestamp <= end) {
                            withinRange = true;
                            break;
                        }
                    } catch (Exception e) {
                        // ignore problematic range entries
                    }
                }
            }

            if (!withinRange) {
                continue;
            }

            try {
                result.add(new ThreadSnapshot(timestamp, data));
            } catch (Exception e) {
                // Skip snapshot creation if constructor fails
            }
        }
    }

    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new java.util.ArrayList<>();
    if (file == null) {
