                try {
                    java.lang.reflect.Method parse = ThreadSnapshot.class.getMethod("parse", String.class);
                    snapshotObj = parse.invoke(null, line);
                } catch (NoSuchMethodException e) {
                    // Fallback to constructor that accepts a String
                    snapshotObj = ThreadSnapshot.class.getConstructor(String.class).newInstance(line);
                }

                if (!(snapshotObj instanceof ThreadSnapshot)) {
                    continue;
                }

                // If time ranges are provided, filter snapshots by timestamp
                if (timeRanges != null && !timeRanges.isEmpty()) {
                    boolean inAnyRange = false;
                    try {
                        java.lang.reflect.Method getTimestamp = snapshotObj.getClass().getMethod("getTimestamp");
                        long ts = (Long) getTimestamp.invoke(snapshotObj);
                        for (ProfileAnalyzeTimeRange range : timeRanges) {
                            try {
                                java.lang.reflect.Method getStart = range.getClass().getMethod("getStart");
                                java.lang.reflect.Method getEnd = range.getClass().getMethod("getEnd");
                                long start = (Long) getStart.invoke(range);
                                long end = (Long) getEnd.invoke(range);
                                if (ts >= start && ts <= end) {
                                    inAnyRange = true;
                                    break;
                                }
                            } catch (Exception ignore) {
                                // Skip malformed range objects
                            }
                        }
                    } catch (Exception ignore) {
                        // If timestamp retrieval fails, skip range filtering
                    }
                    if (!inAnyRange) {
                        continue;
                    }
                }

                result.add((ThreadSnapshot) snapshotObj);
            } catch (Exception e) {
                // Skip lines that cannot be parsed into a ThreadSnapshot
                // Do not propagate the exception to allow processing of remaining lines
            }
        }
    }
