            block.append(line).append(System.lineSeparator());
        }
        // Add the last block if file doesn't end with a blank line
        if (block.length() > 0) {
            ThreadSnapshot snapshot = parseSnapshotBlock(block.toString());
            if (snapshot != null) {
                allSnapshots.add(snapshot);
            }
        }
    } catch (FileNotFoundException e) {
        throw new IOException("File not found: " + file.getAbsolutePath(), e);
    } catch (IOException e) {
        throw new IOException("Error reading file: " + file.getAbsolutePath(), e);
    }
    // If no time ranges provided, return all snapshots
    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }
    List<ThreadSnapshot> filtered = new ArrayList<>();
    for (ThreadSnapshot ts : allSnapshots) {
        long tsTime = ts.getTimestamp();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (tsTime >= range.getBegin() && tsTime <= range.getEnd()) {
                filtered.add(ts);
                break;
            }
        }
    }
    return filtered;
}

/**
 * Parses a single snapshot block (separated by blank lines) into a ThreadSnapshot instance.
 * Expected format of the block:
 *   Timestamp: <epoch_milliseconds>
 *   (optional other header lines)
 *   <stack trace lines>
 * If parsing fails, returns null.
 */
private static ThreadSnapshot parseSnapshotBlock(String block) {
    if (block == null || block.isEmpty()) {
        return null;
    }
    String[] lines = block.split(System.lineSeparator());
    long timestamp = -1;
    StringBuilder stack = new StringBuilder();
    for (String line : lines) {
        if (line.matches("(?i).*timestamp.*")) {
            // Try to extract the first number from the line
            Matcher m = Pattern.compile("(\\d+)").matcher(line);
            if (m.find()) {
                try {
                    timestamp = Long.parseLong(m.group(1));
                } catch (NumberFormatException e) {
                    timestamp = -1;
                }
            }
        } else {
            // Consider all other lines as part of the stack trace
            stack.append(line).append(System.lineSeparator());
        }
    }
    if (timestamp < 0) {
        return null;
    }
    // Trim trailing newline
    String stackStr = stack.toString().trim();
    return new ThreadSnapshot(timestamp, stackStr);
}

