        String line;
        // Simple regex to extract a long value after "timestamp":
        Pattern timestampPattern = Pattern.compile("timestamp\\s*:\\s*(\\d+)");
        while ((line = reader.readLine()) != null) {
            Matcher m = timestampPattern.matcher(line);
            long ts = -1;
            if (m.find()) {
                try {
                    ts = Long.parseLong(m.group(1));
                } catch (NumberFormatException e) {
                    // ignore this line
                    continue;
                }
            } else {
                // If no timestamp found, skip this line
                continue;
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) continue;
                long start = range.getStart(); // assume getter
                long end = range.getEnd();     // assume getter
                if (ts >= start && ts <= end) {
                    inRange = true;
                    break;
                }
            }
            if (!inRange) {
                continue;
            }
            try {
                // Assume ThreadSnapshot has a static parse method
                ThreadSnapshot tsObj = ThreadSnapshot.parse(line);
                result.add(tsObj);
            } catch (Exception e) {
